--
-- Name: app_tenant_in_scope(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.app_tenant_in_scope(row_tenant text) RETURNS boolean
    LANGUAGE sql STABLE
    AS $$
  SELECT
    current_setting('app.is_platform_admin', true) = 'true'
    OR (
      row_tenant IS NOT NULL
      AND row_tenant = ANY (
        string_to_array(
          NULLIF(current_setting('app.allowed_tenant_ids', true), ''),
          ','
        )
      )
    );
$$;


--
-- Name: applications_origin_immutable_fn(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.applications_origin_immutable_fn() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF current_setting('app.allow_origin_correction', true) = 'on' THEN
    RETURN NEW;
  END IF;
  IF NEW.entry_type IS DISTINCT FROM OLD.entry_type THEN
    RAISE EXCEPTION 'applications.entry_type is immutable (use the origin correction workflow)';
  END IF;
  IF OLD.origin_evidence IS NOT NULL
     AND NEW.origin_evidence IS DISTINCT FROM OLD.origin_evidence THEN
    RAISE EXCEPTION 'applications.origin_evidence is immutable once set (use the origin correction workflow)';
  END IF;
  RETURN NEW;
END;
$$;


