--
-- Name: jurisdiction_policy_block_mutation(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.jurisdiction_policy_block_mutation() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NEW.jurisdiction_code IS DISTINCT FROM OLD.jurisdiction_code
     OR NEW.scope IS DISTINCT FROM OLD.scope
     OR NEW.tenant_id IS DISTINCT FROM OLD.tenant_id
     OR NEW.gate_rejects IS DISTINCT FROM OLD.gate_rejects
     OR NEW.gate_lapsed IS DISTINCT FROM OLD.gate_lapsed
     OR NEW.gate_holds IS DISTINCT FROM OLD.gate_holds
     OR NEW.require_disclosure IS DISTINCT FROM OLD.require_disclosure
     OR NEW.require_appeal IS DISTINCT FROM OLD.require_appeal
     OR NEW.require_audit IS DISTINCT FROM OLD.require_audit
     OR NEW.basis IS DISTINCT FROM OLD.basis
     OR NEW.effective_from IS DISTINCT FROM OLD.effective_from
     OR NEW.created_by IS DISTINCT FROM OLD.created_by
     OR NEW.created_at IS DISTINCT FROM OLD.created_at
  THEN
    RAISE EXCEPTION
      'jurisdiction_ai_policy_rules is append-only — fields are immutable except effective_to. Insert a new row to revise the policy.';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: linx_requests_freeze_ownership(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.linx_requests_freeze_ownership() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NEW.tenant_id            IS DISTINCT FROM OLD.tenant_id
     OR NEW.linx_tenant_id    IS DISTINCT FROM OLD.linx_tenant_id
     OR NEW.job_id            IS DISTINCT FROM OLD.job_id
     OR NEW.requested_by_user_id IS DISTINCT FROM OLD.requested_by_user_id THEN
    RAISE EXCEPTION 'linx_requests ownership columns are immutable (tenant_id/linx_tenant_id/job_id/requested_by_user_id)'
      USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END;
$$;


