--
-- Name: run_activity_events; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.run_activity_events WITH (security_invoker='true') AS
 SELECT agent_run_events.run_id,
    'agent'::text AS run_type,
    agent_run_events.tenant_id,
    agent_run_events.type AS event_type,
    agent_run_events.step_name,
    agent_run_events.message,
    agent_run_events.count,
    agent_run_events.payload,
    agent_run_events."timestamp",
    agent_run_events.seq
   FROM public.agent_run_events
UNION ALL
 SELECT pipeline_run_events.run_id,
    'pipeline'::text AS run_type,
    pipeline_run_events.tenant_id,
    pipeline_run_events.type AS event_type,
    pipeline_run_events.step_name,
    pipeline_run_events.message,
    pipeline_run_events.count,
    pipeline_run_events.payload,
    pipeline_run_events."timestamp",
    pipeline_run_events.seq
   FROM public.pipeline_run_events;


--
-- Name: VIEW run_activity_events; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON VIEW public.run_activity_events IS 'SANCTIONED read surface for cross-run activity. Normalizes agent_run_events + pipeline_run_events into a single shape (run_id, run_type, tenant_id, event_type, timestamp, message, payload, step_name, count, seq). Do NOT read the underlying event tables directly for cross-run activity — read this view so consumers stay decoupled from which table an event lives in. Rationale + the deferred full-unification decision: docs/adr/0001-pipeline-run-events.md.';


