--
-- Name: candidate_action_events cae_select; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY cae_select ON public.candidate_action_events FOR SELECT TO lexy_app USING ((public.app_tenant_in_scope(viewer_tenant_id) OR ((viewer_tenant_id IS NULL) AND (EXISTS ( SELECT 1
   FROM public.candidates c
  WHERE ((c.id = candidate_action_events.candidate_id) AND public.app_tenant_in_scope(c.tenant_id)))))));


--
-- Name: candidate_action_events cae_update; Type: POLICY; Schema: public; Owner: -
--

